product_categories = [
  ['Laptop', 'Monitor'],
  ['Keyboard', 'Mouse', 'Webcam'],
  ['Speaker', 'Headphones']
]
letters = ['A', 'B', 'C']

# 1. Print (x, y) coordinates:
for x in range(2): 
  for y in range(3):
    print(f'({x}, {y})')

# 2. Iterate and print all products:
for category in product_categories:
  for product in category:
    print(product)

# 3. Use BREAK in the inner loop when 'B' is found:
for outer_letter in letters:
  for inner_letter in letters:
    print(f'Checking pair: {outer_letter}-{inner_letter}')
    if inner_letter == 'B':
      break
